async function run() {
  let n = 0;
  for (const d of DATA) {
    n += (await prisma.article.updateMany({ where: { title: d.title, bodyAr: null }, data: { titleAr: d.titleAr, excerptAr: d.excerptAr, bodyAr: d.bodyAr } })).count;
  }
  console.log('articles-1 applied:', n);
  await prisma.$disconnect();
}
run().catch((e) => { console.error(e); process.exit(1); });
